parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "decision": {
      "type": "string",
      "enum": [
        "Approve",
        "Denied"
      ]
    },
    "reason": {
      "type": "string",
      "description": "Explanation of the decision. Required detail when Denied; short confirmation when Approved."
    },
    "testCases": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string"
          },
          "title": {
            "type": "string"
          },
          "type": {
            "type": "string",
            "enum": [
              "Positive",
              "Negative",
              "Edge Case"
            ]
          },
          "priority": {
            "type": "string",
            "enum": [
              "High",
              "Medium",
              "Low"
            ]
          },
          "preconditions": {
            "type": "string"
          },
          "requestMethodAndEndpoint": {
            "type": "string"
          },
          "requestHeaders": {
            "type": "string"
          },
          "requestBody": {
            "type": "string"
          },
          "expectedStatusCode": {
            "type": "string"
          },
          "expectedResponseBody": {
            "type": "string"
          },
          "validationPoints": {
            "type": "string"
          }
        },
        "required": [
          "id",
          "title",
          "type",
          "priority",
          "preconditions",
          "requestMethodAndEndpoint",
          "requestHeaders",
          "requestBody",
          "expectedStatusCode",
          "expectedResponseBody",
          "validationPoints"
        ]
      }
    }
  },
  "required": [
    "decision",
    "reason",
    "testCases"
  ]
}

parameters.jsCode:
const result = $json.output;
const testCases = result.testCases || [];

let md = `**Decision:** ${result.decision}

**Reason:** ${result.reason}

`;

if (result.decision === 'Denied') {
  md += `No test cases were generated.
`;
} else {
  md += `## API Test Cases

`;
  for (const tc of testCases) {
    md += `### [${tc.id}] ${tc.title} (${tc.type} / ${tc.priority})
`;
    md += `**Preconditions:** ${tc.preconditions}

`;
    md += `**Request:** ${tc.requestMethodAndEndpoint}

`;
    md += `**Headers:** ${tc.requestHeaders}

`;
    md += `**Request Body:** ${tc.requestBody}

`;
    md += `**Expected Status Code:** ${tc.expectedStatusCode}

`;
    md += `**Expected Response Body:** ${tc.expectedResponseBody}

`;
    md += `**Validation Points:** ${tc.validationPoints}

`;
  }
}

return [{ json: { output: md, decision: result.decision, reason: result.reason, testCases } }];

